import{d as u,C as t,o as c,c as b,j as a,a as o,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第五章","description":"辨天地不仁与刍狗之喻，由橐龠的虚用读到守中。","frontmatter":{"title":"道德经第五章","description":"辨天地不仁与刍狗之喻，由橐龠的虚用读到守中。","category":"guide","aliases":["道德经第五章","老子第五章","dao de jing chapter 5"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-05.md","filePath":"daoism/dao-de-jing/chapter-05.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-05.md"},q=u({...m,setup(g){const s=[{id:"heaven-earth-and-benevolence",label:"天地不仁，以万物为刍狗",showLabel:!0,sentences:[["天地",{text:"不仁",glossary:"buren"},"，以万物为",{text:"刍狗",glossary:"chugou"},"；"],["圣人不仁，以百姓为刍狗。"]],note:["【白话】天地不以刻意施予的仁爱对待万物，把万物看作刍狗；圣人也不以这样的施恩方式治理，把百姓看作刍狗。","【王弼注择要】「天地任自然，无为无造，万物自相治理，故不仁也。」王弼以不造作、不把施恩加在万物之上解释不仁，并以刍与狗各有所用说明万物并非为某一对象特意造就。","【读法】通说以刍狗为祭祀用的草扎狗，王弼此注却从草供兽食、狗供人用立说。读本页应先辨明这一路注法，不能径直把刍狗解释成用完即可丢弃百姓。"]},{id:"the-hollow-bellows",label:"天地之间，其犹橐龠乎",showLabel:!0,sentences:[["天地之间，其犹",{text:"橐龠",glossary:"tuoyue"},"乎？"],["虚而不",{text:"屈",glossary:"qu"},"，动而愈出。"]],note:["【白话】天地之间，不就像橐龠这样的鼓风、通气之器吗？内部空虚却不会穷尽，越是鼓动，气就越能涌出。","【王弼注择要】「橐，排橐也。籥，乐籥也。」又说「天地之中，荡然任自然，故不可得而穷，犹若橐籥也」。注借器具的中空、通气，说明天地的虚用。","【读法】「虚」是中间有空处，因而能够通行、应动；不是主张什么条件都不具备也会凭空生出资源。橐龠通常合称为风箱之喻，王弼分别解释了橐与籥。"]},{id:"words-and-the-empty-centre",label:"多言数穷，不如守中",showLabel:!0,sentences:[["多言",{text:"数",glossary:"shuo"},"穷，不如",{text:"守中",glossary:"shouzhong"},"。"]],note:["【白话】言说与教令过多，屡屡走到困穷，不如守住虚静的内里。","【王弼注择要】「弃己任物，则莫不理。」王弼承接橐籥之喻，反省不断出于己意施为、试图用言说调理一切所造成的困局。","【读法】守中承接前文的中空与任自然，不宜只套成折中、取平均。「多言」也不只是日常话多，放在本章还涉及反复施教、施令。"]}],n=[{id:"buren",term:"不仁",sense:1},{id:"chugou",term:"刍狗",sense:1},{id:"tuoyue",term:"橐龠",sense:1},{id:"qu",term:"屈",sense:1},{id:"shuo",term:"数",sense:1,pinyin:"shuò"},{id:"shouzhong",term:"守中",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五章",tabindex:"-1"},[o("道德经第五章 "),a("a",{class:"header-anchor",href:"#道德经第五章","aria-label":'Permalink to "道德经第五章"'},"​")],-1)),r(i,{title:"从不仁的疑问，读到虚中的作用",summary:"「天地不仁」容易使人先想到冷酷。本章循王弼注，先看他为何以任自然释不仁，再借橐龠说明中空而能用，最后回到多言与守中。重点在减少造作，不在取消人的关怀与责任。",points:[{label:"先读",text:"王弼所批评的施恩造作是什么？"},{label:"再辨",text:"橐龠的中空怎样使鼓动成为可能？"},{label:"后想",text:"守中与少说几句话有何区别？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:s,glossary:n,tone:"ink",density:"comfortable","aria-label":"《道德经》第五章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"天地不仁，以万物为刍狗。",tone:"辨义",guide:"不仁须与注中任自然、无为无造连读。若直接按现代日常语理解成残酷，就会越过本章对施化造作的反省。"},{text:"虚而不屈，动而愈出。",tone:"设喻",guide:"橐龠之喻既说虚，也说动。只有空无而无实际响应，并不能概括这里的作用关系。"},{text:"多言数穷，不如守中。",tone:"收束",guide:"结尾沿着器具的中空，转向处事时不被己意填满。守中的内在余地，比表面少说几句话更关键。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么天地与圣人都被说成「不仁」" tabindex="-1">象：为什么天地与圣人都被说成「不仁」？ <a class="header-anchor" href="#象-为什么天地与圣人都被说成「不仁」" aria-label="Permalink to &quot;象：为什么天地与圣人都被说成「不仁」？&quot;">​</a></h3><p>前一句说天地，后一句说圣人，构成由天地运行到治理方式的类比。王弼认为，若把万物的存在理解成一个施恩者有意安排的结果，就会遮蔽万物各自的适用与生成；他因而以任自然、无为无造释不仁。这是古注的解释路径，不是把现代所说的恶意伤害合理化。</p><h3 id="理-橐龠与「不仁」有什么联系" tabindex="-1">理：橐龠与「不仁」有什么联系？ <a class="header-anchor" href="#理-橐龠与「不仁」有什么联系" aria-label="Permalink to &quot;理：橐龠与「不仁」有什么联系？&quot;">​</a></h3><p>橐龠内部不预先填满，才能随鼓动而通气。王弼借此说明，不以己意造立、安排一切，反而给万物的作用留下余地。由不仁读到虚用，再到守中，三段都在反省主观施为过满；但器物之喻不能直接证明每个现实社会都会自行得到妥善治理。</p><h3 id="用-守中是否就是遇事不干预" tabindex="-1">用：守中是否就是遇事不干预？ <a class="header-anchor" href="#用-守中是否就是遇事不干预" aria-label="Permalink to &quot;用：守中是否就是遇事不干预？&quot;">​</a></h3><p>要先判断干预是否出于现实需要，是否帮助当事人恢复行动的条件。遇到危险、侵害或基本需要缺失，不能借不仁与任自然袖手旁观。本章能启发人少些控制冲动，却不能替代具体责任；反复发布命令也未必比有准备、有回应的支持更有效。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>帮助别人时，给对方留出位置。</strong> 教学或协作中，可以先问清困难、提供必要支持，再让对方尝试。若每一步都代为安排，帮助就可能变成控制。留白需要条件与回应，不能省去应有的照顾。</p><p><strong>让沟通有依据、有后续。</strong> 面对混乱，先查信息、资源或分工出了什么问题，再决定是否需要补充说明。不断重复口号、频繁改口，容易使人更无所适从；守中可借来提醒自己在行动前稳住判断，而不是以沉默替代沟通。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：最近一次帮助别人，是在解决对方的实际困难，还是在满足自己安排一切的需要？哪些支持必须给，哪些空间可以交还？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>「刍狗」通说为草扎的祭犬，王弼本章注则分说刍与狗各有所用；两种说明不混作同一条注释。其重点并非给弃置百姓提供理由。</li><li>本页沿用「橐龠」，HFL 录文作「橐籥」；籥与龠在此关联通气器具。屈读 qū，取穷尽义；数读 shuò，取屡次义。</li><li>「守中」依橐龠中虚及王弼「弃己任物」的注意理解，不直接等同于后来的中庸或凡事折中。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，004a–004b</a>。</p>',15))])}}});export{_ as __pageData,q as default};
